// Permission Query Condition بصيغة JavaScript
frappe.permissions.get_permission_query_conditions = function(doc, user) {
    if (!user) return "";

    // إذا كان المستخدم Projects Manager → يرى كل المشاريع
    if (frappe.user_roles.includes("Projects Manager")) {
        return "";
    }

    // إذا كان المستخدم Projects User → يرى فقط المشاريع التي هو Owner لها
    // أو عضو ضمن فريق المشروع (Project User child table)
    if (frappe.user_roles.includes("Projects User")) {
        return `(
            \`tabProject\`.\`owner\` = '${user}'
            OR EXISTS (
                SELECT 1 FROM \`tabProject User\`
                WHERE \`tabProject User\`.\`parent\` = \`tabProject\`.\`name\`
                  AND \`tabProject User\`.\`user\` = '${user}'
            )
        )`;
    }

    return "";
};

frappe.ui.form.on('Overtime Items', { 
    from_time: function(frm, cdt, cdn) {
        calculate_total_hours(frm, cdt, cdn);
    },
    to_time: function(frm, cdt, cdn) {
        calculate_total_hours(frm, cdt, cdn);
    }
});

function calculate_total_hours(frm, cdt, cdn) {
    let child = locals[cdt][cdn];

    if (child.from_time && child.to_time) {
        // تحويل الوقت من نص إلى كائن وقت يمكن طرحه
        let start = moment(child.from_time, 'HH:mm:ss');
        let end = moment(child.to_time, 'HH:mm:ss');

        // حساب الفرق بالدقائق
        let duration = moment.duration(end.diff(start));
        let hours = duration.asHours();

        // التعامل مع حالة تجاوز منتصف الليل (إذا كان الوقت "إلى" أصغر من "من")
        if (hours < 0) {
            hours += 24;
        }

        // وضع القيمة في حقل المجموع وتقريبها لمرتبتين عشريتين
        frappe.model.set_value(cdt, cdn, 'total_hours', hours.toFixed(2));
    }
}

frappe.ui.form.on('Employee Checkin', {
    after_save: function(frm) {
        console.log('Employee Checkin:', frm.doc);

        // Check if the log_type is "IN"
        if (frm.doc.log_type === "IN") {
            let attendance_date = frm.doc.time.split(' ')[0]; // Extract the date
            console.log('Attendance Date:', attendance_date);

            // Fetch existing attendance record for the employee on that date
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Attendance",
                    filters: {
                        employee: frm.doc.employee,
                        attendance_date: attendance_date
                    },
                    limit_page_length: 1
                },
                callback: function(data) {
                    console.log('Attendance Records Found:', data.message);

                    // Fetch the employee name using the employee ID
                    frappe.call({
                        method: "frappe.client.get",
                        args: {
                            doctype: "Employee",
                            name: frm.doc.employee
                        },
                        callback: function(emp_data) {
                            let employee_name = emp_data.message ? emp_data.message.employee_name : "Unknown Employee";

                            if (data.message && data.message.length) {
                                // Attendance exists, update it
                                let attendance_doc = data.message[0];
                                frappe.call({
                                    method: "frappe.client.set_value",
                                    args: {
                                        doctype: "Attendance",
                                        name: attendance_doc.name,
                                        fieldname: {
                                            "status": "Present",
                                            "check_in": frm.doc.time // Update check-in time if needed
                                        }
                                    },
                                    callback: function(r) {
                                        if (!r.exc) {
                                            frappe.msgprint(__('Attendance updated to Present for employee: {0} at {1}.', [employee_name, frm.doc.time]));
                                        } else {
                                            frappe.msgprint(__('Error updating attendance.'));
                                        }
                                    }
                                });
                            } else {
                                // Attendance does not exist, create a new one
                                frappe.call({
                                    method: "frappe.client.insert",
                                    args: {
                                        doc: {
                                            "doctype": "Attendance",
                                            "employee": frm.doc.employee,
                                            "attendance_date": attendance_date,
                                            "status": "Present",
                                            "check_in": frm.doc.time
                                        }
                                    },
                                    callback: function(r) {
                                        if (!r.exc) {
                                            frappe.msgprint(__('Attendance recorded as Present for employee: {0} at {1}.', [employee_name, frm.doc.time]));
                                        } else {
                                            frappe.msgprint(__('Error creating attendance.'));
                                        }
                                    }
                                });
                            }
                        }
                    });
                }
            });
        } else {
            console.log('Log type is not IN. Current log type:', frm.doc.log_type);
        }
    }
});

