    onload: function (listview) {
        // Fetch app path once (cached)
        let APP_PATH = null;

        const getAppPath = async () => {
            if (APP_PATH) return APP_PATH;

            try {
                const r = await frappe.call({
                    method: 'fingerprint.api.fetch_checkins.get_app_info',
                    freeze: false
                });
                if (r.message && r.message.app_path) {
                    APP_PATH = r.message.app_path;
                    console.log('✅ Fingerprint app path:', APP_PATH);
                    return APP_PATH;
                } else {
                    throw new Error('App path not returned');
                }
            } catch (e) {
                frappe.show_alert({
                    message: __('⚠️ Using fallback path — app info not available'),
                    indicator: 'orange'
                }, 5);
                console.warn('Falling back to default app path structure');
                // Fallback: construct path assuming standard bench layout
                // e.g., site = 'moi-mis.gov.sy' → user = 'moi-mis'
                const site = frappe.boot.site || 'moi-mis.gov.sy';
                const user = site.split('.')[0]; // 'moi-mis'
                APP_PATH = `/home/${user}/frappe-bench/apps/fingerprint`;
                return APP_PATH;
            }
        };

        // Button 1: Fetch Checkins (unchanged)
        listview.page.add_button(__('Fetch Checkins'), () => {
            const d = new frappe.ui.Dialog({
                title: __('Fetch Checkins'),
                fields: [
                    {
                        label: __('Import Start Date'),
                        fieldname: 'import_start_date',
                        fieldtype: 'Date',
                        reqd: 1,
                        default: frappe.datetime.add_days(frappe.datetime.nowdate(), -7)
                    },
                    {
                        label: __('Import End Date'),
                        fieldname: 'import_end_date',
                        fieldtype: 'Date',
                        reqd: 1,
                        default: frappe.datetime.nowdate()
                    }
                ],
                primary_action_label: __('Fetch'),
                primary_action: function (values) {
                    frappe.call({
                        method: 'fingerprint.api.fetch_checkins.fetch_checkins',
                        args: {
                            import_start_date: values.import_start_date,
                            import_end_date: values.import_end_date
                        },
                        freeze: true,
                        freeze_message: __('Fetching check-ins, please wait...'),
                        callback: function (r) {
                            if (!r.exc) {
                                frappe.msgprint(__('✅ Check-ins fetched successfully'));
                                d.hide();
                                listview.refresh();
                            } else {
                                let error_msg = r.exc || __('Unknown error');
                                if (error_msg.includes('Traceback')) {
                                    const lines = error_msg.split('\n');
                                    const errorLine = lines.find(line =>
                                        line.includes('Exception:') ||
                                        line.includes('Error:') ||
                                        (line.trim() && !line.startsWith(' '))
                                    );
                                    error_msg = errorLine ? errorLine.trim() : __('Operation failed.');
                                }
                                frappe.msgprint({
                                    title: __('❌ Fetch Failed'),
                                    indicator: 'red',
                                    message: __('Failed to fetch check-ins: {0}', [error_msg])
                                });
                                console.error('Fetch error:', r.exc);
                            }
                        }
                    });
                }
            });
            d.show();
        });

        // Button 2: Mark Attendance (unchanged)
        listview.page.add_button(__('Mark Attendance'), () => {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Shift Type',
                    fields: ['name'],
                    order_by: 'name'
                },
                callback: function (r) {
                    if (r.message && r.message.length > 0) {
                        const shift_options = ['All Shifts'].concat(r.message.map(s => s.name));
                        const d = new frappe.ui.Dialog({
                            title: __('Mark Attendance'),
                            fields: [
                                {
                                    label: __('Select Shift Type'),
                                    fieldname: 'shift_type',
                                    fieldtype: 'Select',
                                    options: shift_options,
                                    default: 'All Shifts',
                                    reqd: 1
                                },
                                {
                                    label: __('Process attendance after'),
                                    fieldname: 'process_attendance_after',
                                    fieldtype: 'Date',
                                    reqd: 1,
                                    default: frappe.datetime.add_days(frappe.datetime.nowdate(), -30)
                                },
                                {
                                    label: __('Last sync of checkin'),
                                    fieldname: 'last_sync_of_checkin',
                                    fieldtype: 'Datetime',
                                    reqd: 1,
                                    default: frappe.datetime.now_datetime()
                                }
                            ],
                            primary_action_label: __('Process'),
                            primary_action: function (values) {
                                d.hide();
                                frappe.call({
                                    method: 'fingerprint.api.mark_attendance.process_auto_attendance_for_all_shifts',
                                    args: {
                                        process_attendance_after: values.process_attendance_after,
                                        last_sync_of_checkin: values.last_sync_of_checkin,
                                        shift_type: values.shift_type === 'All Shifts' ? '' : values.shift_type
                                    },
                                    freeze: true,
                                    freeze_message: __('Marking attendance...'),
                                    callback: function (r) {
                                        if (!r.exc) {
                                            frappe.msgprint(__('✅ Attendance marked for: {0}', [values.shift_type]));
                                        } else {
                                            frappe.msgprint(__('❌ Failed: ') + (r.exc || 'Unknown error'));
                                        }
                                        listview.refresh();
                                    }
                                });
                            }
                        });
                        d.show();
                    } else {
                        frappe.msgprint(__('No Shift Types found. Create one first.'));
                    }
                }
            });
        });

        // Button 3: Fetch & Upload (✅ Updated with dynamic app path)
        listview.page.add_inner_button(__('Fetch & Upload'), async function () {
            loadJSZipAndFileSaver(async function () {
                const companies = await frappe.db.get_list('Company', {
                    fields: ['name'],
                    order_by: 'name'
                }).catch(() => []);

                const dialog = new frappe.ui.Dialog({
                    title: __('Enter Configuration'),
                    fields: [
                        {
                            label: __('Company'),
                            fieldname: 'company',
                            fieldtype: 'Link',
                            options: 'Company',
                            reqd: 1,
                            default: frappe.defaults.get_default('company') || (companies.length ? companies[0].name : '')
                        },
                        {
                            label: __('Device IPs'),
                            fieldname: 'device_ips',
                            fieldtype: 'Data',
                            default: localStorage.getItem('fingerprint_device_ips') || '',
                            description: __('Comma-separated, e.g., 192.168.1.10, 192.168.1.11'),
                            reqd: 1
                        },
                        {
                            label: __('Username'),
                            fieldname: 'username',
                            fieldtype: 'Data',
                            reqd: 1,
                            default: frappe.session.user
                        },
                        {
                            label: __('Password'),
                            fieldname: 'password',
                            fieldtype: 'Password',
                            reqd: 1
                        }
                    ],
                    primary_action_label: __('Generate & Download ZIP'),
                    primary_action: async function (values) {
                        dialog.hide();

                        try {
                            // ✅ Get app path dynamically
                            const appPath = await getAppPath();
                            const main_file_path = `${appPath}/fingerprint/api/get_fingerprint_data.py`;
                            const extra_file_path = `${appPath}/fingerprint/api/run_python.bat`;

                            const zip = new JSZip();

                            // Read main file
                            const mainRes = await frappe.call({
                                method: 'fingerprint.api.read_file_from_server.read_server_file',
                                args: { file_path: main_file_path }
                            });

                            if (!mainRes.message) throw new Error(__('Main config file not found'));

                            let content = mainRes.message.content
                                .replace(/USERNAME/g, values.username)
                                .replace(/PASSWORD/g, values.password)
                                .replace(/COMPANY/g, values.company)
                                .replace(/IPs/g, values.device_ips);

                            zip.file(mainRes.message.file_name, content);

                            // Optional: extra file
                            try {
                                const extraRes = await frappe.call({
                                    method: 'fingerprint.api.read_file_from_server.read_server_file',
                                    args: { file_path: extra_file_path }
                                });
                                if (extraRes.message) {
                                    zip.file(extraRes.message.file_name, extraRes.message.content);
                                }
                            } catch (e) {
                                console.warn('Extra file not found, skipping');
                            }

                            // Download
                            const blob = await zip.generateAsync({ type: 'blob' });
                            const filename = `fingerprint_config_${values.company.replace(/\s+/g, '_')}.zip`;
                            saveAs(blob, filename);
                            frappe.msgprint(__('✅ ZIP generated for {0}', [values.company]));

                            // Save IPs
                            localStorage.setItem('fingerprint_device_ips', values.device_ips);

                        } catch (err) {
                            frappe.msgprint(__('❌ Error: {0}', [err.message || err]));
                            console.error('ZIP generation error:', err);
                        }
                    }
                });
                dialog.show();
            });
        });

        // Button 4: Export to Excel (unchanged)
        listview.page.add_inner_button(__('Export to Excel'), async function () {
            loadSheetJS(() => {
                try {
                    const data = listview.data;
                    if (!data || data.length === 0) {
                        frappe.msgprint(__('No data to export'));
                        return;
                    }

                    const export_data = data.map(row => ({
                        'Employee': row.employee,
                        'Employee Name': row.employee_name,
                        'Attendance Date': frappe.datetime.str_to_user(row.attendance_date),
                        'Status': row.status,
                        'In Time': row.in_time || '',
                        'Out Time': row.out_time || '',
                        'Working Hours': (row.total_working_hours || 0).toFixed(2),
                        'Late Entry (Min)': row.custom_late_entry_in_minutes || 0,
                        'Early Exit (Min)': row.custom_early_exit_in_minutes || 0
                    }));

                    const ws = XLSX.utils.json_to_sheet(export_data);
                    const wb = XLSX.utils.book_new();
                    XLSX.utils.book_append_sheet(wb, ws, 'Attendance');
                    XLSX.writeFile(wb, `Attendance_${frappe.datetime.get_today()}.xlsx`);

                    frappe.show_alert(__('Exported successfully'), 'green');
                } catch (err) {
                    frappe.msgprint(__('Export failed: ') + err.message);
                    console.error(err);
                }
            });
        });
    }
};

// ==== Utility Functions (unchanged) ====
function loadSheetJS(callback) {
    if (window.XLSX) return callback();
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
    script.onload = callback;
    script.onerror = () => frappe.msgprint(__('Failed to load Excel library'));
    document.head.appendChild(script);
}

function loadJSZipAndFileSaver(callback) {
    if (window.JSZip && window.saveAs) return callback();
    loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js', () =>
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/FileSaver.js/2.0.5/FileSaver.min.js', callback)
    );
}

function loadScript(src, callback) {
    const script = document.createElement('script');
    script.src = src;
    script.onload = callback;
    script.onerror = () => frappe.throw(__('Failed to load: ') + src);
    document.head.appendChild(script);
}

