function calculate_final_dues(frm) {
	let total_earnings = 0;
	let total_deductions = 0;
   console.log('doc.dues_components',frm.doc.dues_components);
	(frm.doc.dues_components).forEach(row => { 

	    console.log('doc.dues_components',row.dues_component);
		let amount = flt(row.dues_amount);

		if (!amount) return;

		// Earnings
		if (["Salary Due", "Leave Encashment", "Compensation"].includes(row.dues_component)) {
			total_earnings += amount;
		}

		// Deductions
		if (row.dues_component === "Deduction") {
			total_deductions += amount;
		}
	});

	frm.set_value("total_earnings", total_earnings);
	frm.set_value("total_deduction", total_deductions);
	frm.set_value("net_payable", total_earnings - total_deductions);
}
