    // filter "case" link field based on selected employee
    frm.set_query("case", function () {
      return {
        filters: {
          employee: frm.doc.final_dues_employee || ""
        }
      };
    });
  },

  final_dues_employee(frm) {
    // when employee changes, clear case and refresh options
    frm.set_value("case", null);
    frm.refresh_field("case");
  }
});

// ======================================================
// Employee Separation Case - Client Script (Full Copy/Paste)
// Features:
// 1) On NEW case: auto-focus on 2nd tab (case_details_tab) once
// 2) Dashboard with colored cards + Next Action
// 3) Employee card (image, id, name, DOJ, dept, office, designation)
// 4) Case Details card same height as employee card
// 5) Mobile fix: Case Details layout uses CSS grid (no bootstrap row/col overflow)
// 6) HR05 (Resignation Request) card + step ONLY when Case Type = "Resignation"
// ======================================================

frappe.ui.form.on("Employee Separation Case", {
  refresh(frm) {
    // Focus on Case Details tab only for NEW docs and only once
    if (frm.is_new() && !frm.__case_details_tab_clicked) {
      frm.__case_details_tab_clicked = true;
      setTimeout(() => activate_tab(frm, "case_details_tab"), 150);
    }

    // Build dashboard
    build_separation_dashboard(frm);
  }
});

// --------------------------
// TAB ACTIVATION (reliable)
// --------------------------
function activate_tab(frm, tab_fieldname) {
  const f = frm.get_field(tab_fieldname);
  if (f && f.$tab && f.$tab.length) {
    f.$tab.trigger("click");
    return;
  }

  const $li = frm.$wrapper.find(`li[data-fieldname="${tab_fieldname}"]`);
  if ($li.length) {
    $li.trigger("click");
    return;
  }

  const $a = frm.$wrapper.find(`a[data-fieldname="${tab_fieldname}"]`);
  if ($a.length) $a.trigger("click");
}

// --------------------------
// CASE TYPE HELPER
// --------------------------
function is_resignation_case(frm) {
  return (frm.doc.case_type || "").trim() === "Resignation";
}

// =========================
// THEME COLORS PER DOCTYPE
// =========================
const SEP_THEME = {
  "Resignation Request": {
    badge_bg: "#E8F0FE",
    badge_color: "#1A73E8",
    card_border: "#1A73E8",
    btn_class: "btn-primary"
  },
  "Exit Interview Minutes": {
    badge_bg: "#E6FCF5",
    badge_color: "#0CA678",
    card_border: "#0CA678",
    btn_class: "btn-success"
  },
  "Clearance": {
    badge_bg: "#FFF4E6",
    badge_color: "#E8590C",
    card_border: "#E8590C",
    btn_class: "btn-warning"
  },
  "Final Dues Statement": {
    badge_bg: "#F3F0FF",
    badge_color: "#7048E8",
    card_border: "#7048E8",
    btn_class: "btn-info"
  }
};

// =========================
// MAIN BUILDER
// =========================
async function build_separation_dashboard(frm) {
  if (!frm.fields_dict.dashboard_html || !frm.fields_dict.dashboard_html.$wrapper) return;

  if (frm.is_new()) {
    frm.fields_dict.dashboard_html.$wrapper.html(
      `<div class="text-muted">Save the case to enable dashboard actions.</div>`
    );
    return;
  }

  const show_hr05 = is_resignation_case(frm);

  // Fetch linked docs by same case (HR05 only needed for resignation, but safe to fetch anyway)
  const hr05 = await get_doc_status_by_case("Resignation Request", frm.doc.name);
  const hr07 = await get_doc_status_by_case("Exit Interview Minutes", frm.doc.name);
  const hr08 = await get_doc_status_by_case("Clearance", frm.doc.name);
  const hr09 = await get_doc_status_by_case("Final Dues Statement", frm.doc.name);

  // Fetch employee brief (including image)
  const emp = await get_employee_brief(frm.doc.employee);

  // Next action logic (case-type aware)
  const next = get_next_action(frm, { hr05, hr07, hr08, hr09 });

  // Next theme (optional coloring)
  const nextTheme = {
    HR05: SEP_THEME["Resignation Request"],
    HR07: SEP_THEME["Exit Interview Minutes"],
    HR08: SEP_THEME["Clearance"],
    HR09: SEP_THEME["Final Dues Statement"]
  }[next.action] || {};

  const nextBg = nextTheme.badge_bg || "#e7f5ff";
  const nextColor = nextTheme.badge_color || "#1864ab";
  const nextBorder = nextTheme.card_border || "#cfe2ff";
  const nextBtnClass = nextTheme.btn_class || "btn-primary";

  // Cards HTML (HR05 only if resignation)
  const cards_html = `
    <div class="row" style="gap:12px; margin:0;">
      ${show_hr05 ? dash_card("HR05 Resignation", hr05, "Resignation Request") : ""}
      ${dash_card("HR07 Exit Interview", hr07, "Exit Interview Minutes")}
      ${dash_card("HR08 Clearance", hr08, "Clearance")}
      ${dash_card("HR09 Final Dues", hr09, "Final Dues Statement")}
    </div>
  `;

  // Render HTML
  const html = `
    <div style="margin-bottom:12px;">
      <div class="alert" style="border-radius:12px; margin:0; background:${nextBg}; color:${nextColor}; border:1px solid ${nextBorder};">
        <b>Next Action:</b> ${frappe.utils.escape_html(next.label)}
        ${next.action !== "DONE" ? `
          <button type="button" class="btn btn-sm ${nextBtnClass} pull-right dash-next-btn" data-action="${next.action}">
            Go
          </button>` : ""
        }
      </div>
    </div>

    ${cards_html}

    ${info_grid(frm, emp)}
  `;

  frm.fields_dict.dashboard_html.$wrapper.html(html);

  // Card buttons -> Open/Create
  frm.fields_dict.dashboard_html.$wrapper
    .find(".dash-btn")
    .off("click")
    .on("click", function () {
      open_or_create_by_case(frm, $(this).data("doctype"));
    });

  // Next action button
  frm.fields_dict.dashboard_html.$wrapper
    .find(".dash-next-btn")
    .off("click")
    .on("click", function () {
      const action = $(this).data("action");
      if (action === "HR05") open_or_create_by_case(frm, "Resignation Request");
      if (action === "HR07") open_or_create_by_case(frm, "Exit Interview Minutes");
      if (action === "HR08") open_or_create_by_case(frm, "Clearance");
      if (action === "HR09") open_or_create_by_case(frm, "Final Dues Statement");
    });
}

// =========================
// UI COMPONENTS
// =========================
function dash_card(title, info, doctype) {
  const status = info.exists ? (info.state || "Unknown") : "Not Started";
  const btnText = info.exists ? "Open" : "Create";

  const t = SEP_THEME[doctype] || {};
  const badgeBg = t.badge_bg || "#f1f3f5";
  const badgeColor = t.badge_color || "#333";
  const borderColor = t.card_border || "#dee2e6";
  const btnClass = t.btn_class || "btn-dark";

  return `
    <div class="col" style="min-width:260px; padding:0;">
      <div class="card" style="padding:14px; border-radius:14px; border:1px solid ${borderColor};">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
          <div style="font-weight:800;">${frappe.utils.escape_html(title)}</div>
          <span class="badge" style="
              padding:6px 10px;
              border-radius:999px;
              background:${badgeBg};
              color:${badgeColor};
              font-weight:800;">
            ${frappe.utils.escape_html(status)}
          </span>
        </div>

        <button type="button" class="btn ${btnClass} btn-sm dash-btn"
          data-doctype="${doctype}"
          style="width:100%; border-radius:10px;">
          ${btnText}
        </button>
      </div>
    </div>
  `;
}

