    <div class="esc-info-wrap" style="margin:12px 0 0 0; display:flex; gap:12px; align-items:stretch; flex-wrap:wrap;">
      <!-- Left: Employee -->
      <div class="esc-info-col" style="flex:1; min-width:300px; display:flex;">
        <div class="card" style="
          padding:14px; border-radius:14px;
          width:100%; height:100%; min-height:${MIN_H}px;
          display:flex; flex-direction:column;
          box-sizing:border-box; overflow:hidden;
        ">
          <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
            ${avatar}
