// =========================
// NEXT ACTION LOGIC
// =========================
function get_next_action(frm, { hr05, hr07, hr08, hr09 }) {
  const APPROVED = "Approved"; // adjust to your workflow final state
  const resignation = is_resignation_case(frm);

  // Only resignation requires HR05
  if (resignation) {
    if (!hr05.exists || hr05.state !== APPROVED)
      return { label: "Complete HR05 (Resignation Request)", action: "HR05" };
  }

  // All case types continue with HR07 -> HR08 -> HR09
  if (!hr07.exists || hr07.state !== APPROVED)
    return { label: "Complete HR07 (Exit Interview)", action: "HR07" };

  if (!hr08.exists || hr08.state !== APPROVED)
    return { label: "Complete HR08 (Clearance)", action: "HR08" };

  if (!hr09.exists || hr09.state !== APPROVED)
    return { label: "Complete HR09 (Final Dues)", action: "HR09" };

  return { label: "All steps completed. Proceed to close case.", action: "DONE" };
}

// =========================
// DATA FETCHERS
// =========================
function get_doc_status_by_case(doctype, case_name) {
  return new Promise((resolve) => {
    frappe.call({
      method: "frappe.client.get_value",
      args: {
        doctype,
        filters: { case: case_name },
        fieldname: ["name", "workflow_state"]
      },
      callback: function (r) {
        const msg = r.message || null;
        if (msg && msg.name) resolve({ exists: true, name: msg.name, state: msg.workflow_state });
        else resolve({ exists: false, name: null, state: null });
      }
    });
  });
}

function get_employee_brief(employee_id) {
  return new Promise((resolve) => {
    if (!employee_id) return resolve(null);

    frappe.call({
      method: "frappe.client.get_value",
      args: {
        doctype: "Employee",
        filters: { name: employee_id },
        fieldname: ["employee_name", "date_of_joining", "department", "custom_office", "designation", "image"]
      },
      callback: (r) => resolve(r.message || null)
    });
  });
}

// =========================
// OPEN / CREATE LINKED DOC
// =========================
function open_or_create_by_case(frm, target_doctype) {
  frappe.call({
    method: "frappe.client.get_value",
    args: {
      doctype: target_doctype,
      filters: { case: frm.doc.name },
      fieldname: "name"
    },
    callback: function (r) {
      const name = r.message && r.message.name;

      if (name) {
        frappe.set_route("Form", target_doctype, name);
      } else {
        frappe.new_doc(target_doctype, {
          case: frm.doc.name,
          employee: frm.doc.employee
        });
      }
    }
  });
}

frappe.ui.form.on('Interview Round', {
    setup: function(frm) {
        // إخفاء الحقول الأصلية غير المستخدمة مؤقتاً
        frm.set_df_property('expected_average_rating', 'hidden', 1);
        frm.set_df_property('average_rating', 'hidden', 1);
    },
    
    refresh: function(frm) {
        // إضافة أزرار مخصصة
        frm.add_custom_button(__('توزيع الأوزان تلقائياً'), () => {
            distribute_weights_evenly(frm);
        }, __('إجراءات'));
        
        frm.add_custom_button(__('إضافة أسئلة نموذجية'), () => {
            add_sample_questions(frm);
        }, __('إجراءات'));
        
        // التحقق والحساب عند التحديث
        validate_weights(frm);
        calculate_final_score(frm);
        
        // تحديث واجهة الأوزان
        update_weight_indicator(frm);
    },
    
    // عند إضافة عضو جديد
    panel_members_add: function(frm, cdt, cdn) {
        setTimeout(() => {
            // تعيين وزن افتراضي ذكي
            const members = frm.doc.panel_members || [];
            const new_weight = (100 / members.length).toFixed(1);
            frappe.model.set_value(cdt, cdn, 'weight', parseFloat(new_weight));
            
            validate_weights(frm);
            update_weight_indicator(frm);
        }, 300);
    },
    
    // عند حذف عضو
    panel_members_remove: function(frm) {
        validate_weights(frm);
        calculate_final_score(frm);
        update_weight_indicator(frm);
    },
    
    // عند تغيير وزن العضو
    'panel_members.weight': function(frm, cdt, cdn) {
        validate_weights(frm);
        calculate_final_score(frm);
        update_weight_indicator(frm);
    },
    
    // عند تغيير درجة السؤال
    'interview_questions.given_score': function(frm, cdt, cdn) {
        update_question_percentage(cdt, cdn);
        calculate_member_score(cdt, cdn);
        calculate_final_score(frm);
    },
    
    // عند تغيير الدرجة القصوى للسؤال
    'interview_questions.max_score': function(frm, cdt, cdn) {
        update_question_percentage(cdt, cdn);
        calculate_member_score(cdt, cdn);
        calculate_final_score(frm);
    },
    
    // عند إضافة سؤال جديد
    interview_questions_add: function(frm, cdt, cdn) {
        setTimeout(() => {
            frappe.model.set_value(cdt, cdn, 'max_score', 10);
            frappe.model.set_value(cdt, cdn, 'given_score', 0);
        }, 100);
    }
});

// ========================================
// الدوال المساعدة
// ========================================

// 1. تحديث نسبة السؤال فوراً
function update_question_percentage(cdt, cdn) {
    const question = frappe.get_doc(cdt, cdn);
    if (question.max_score && question.max_score > 0) {
        const percentage = (question.given_score / question.max_score) * 100;
        frappe.model.set_value(cdt, cdn, 'score_percentage', 
            Math.min(100, Math.max(0, parseFloat(percentage.toFixed(1)))));
    }
}

// 2. حساب درجة العضو من أسئلته
function calculate_member_score(cdt, cdn) {
    const member = frappe.get_doc(cdt, cdn);
    const questions = frappe.model.get_doc(cdt, cdn).interview_questions || [];
    
    let total_score = 0;
    let max_possible = 0;
    
    questions.forEach(q => {
        total_score += parseFloat(q.given_score || 0);
        max_possible += parseFloat(q.max_score || 0);
    });
    
    frappe.model.set_value(cdt, cdn, 'member_score', total_score);
    frappe.model.set_value(cdt, cdn, 'member_max_score', max_possible);
    
    // إعادة حساب المساهمة إذا كان الوزن موجوداً
    if (max_possible > 0 && member.weight > 0) {
        const ratio = total_score / max_possible;
        const contribution = ratio * member.weight;
        frappe.model.set_value(cdt, cdn, 'contribution', parseFloat(contribution.toFixed(2)));
    } else {
        frappe.model.set_value(cdt, cdn, 'contribution', 0);
    }
}

// 3. التحقق من مجموع الأوزان = 100%
function validate_weights(frm) {
    const members = frm.doc.panel_members || [];
    let total = 0;
    
    members.forEach(row => {
        total += parseFloat(row.weight || 0);
    });
    
    total = Math.round(total * 10) / 10; // تقريب لتجنب أخطاء الفاصلة العائمة
    frm.set_value('custom_total_weight', total);
    
    // منع الحفظ إذا لم يساوِ 100%
    if (frm.doc.__unsaved && Math.abs(total - 100) > 0.2) {
        frm.disable_save();
    } else {
        frm.enable_save();
    }
}

// 4. تحديث مؤشر الأوزان في الواجهة
function update_weight_indicator(frm) {
    const total = frm.doc.custom_total_weight || 0;
    
    if (Math.abs(total - 100) < 0.2) {
        frm.page.set_indicator(__('✅ الأوزان صحيحة'), 'green');
    } else if (total > 100) {
        frm.page.set_indicator(__('❌ {0}% (زيادة)', [total.toFixed(1)]), 'red');
    } else {
        frm.page.set_indicator(__('⚠️ {0}% (ناقص)', [total.toFixed(1)]), 'orange');
    }
}

// 5. حساب الدرجة النهائية
function calculate_final_score(frm) {
    const members = frm.doc.panel_members || [];
    let final_score = 0;
    let all_complete = true;
    
    members.forEach(member => {
        const member_doc = frappe.model.get_doc(member.doctype, member.name);
        const questions = member_doc.interview_questions || [];
        
        // تخطي العضو إذا لم تُدخل درجات الأسئلة
        if (questions.length > 0 && member_doc.member_score === 0) {
            all_complete = false;
        }
        
        // جمع المساهمات
        final_score += parseFloat(member_doc.contribution || 0);
    });
    
    // تحديث الدرجة النهائية فقط إذا كانت كاملة
    if (members.length > 0 && all_complete && Math.abs(frm.doc.custom_total_weight - 100) < 0.2) {
        final_score = Math.min(100, Math.max(0, parseFloat(final_score.toFixed(2))));
        frm.set_value('final_score', final_score);
        
        // تحديث الحالة
        frm.set_value('result_status', final_score >= 70 ? 'ناجح ✅' : 'مرفوض ❌');
    } else {
        frm.set_value('custom_final_score', 0);
        if (members.length > 0) {
            frm.set_value('custom_result_status', 'قيد المراجعة');
        }
    }
}

// 6. توزيع الأوزان تلقائياً
function distribute_weights_evenly(frm) {
    const members = frm.doc.panel_members || [];
    if (members.length === 0) {
        frappe.msgprint(__('⚠️ أضف أعضاء اللجنة أولاً'));
        return;
    }
    
    const weight_per_member = (100 / members.length).toFixed(1);
    let promises = [];
    
    members.forEach(row => {
        promises.push(
            frappe.model.set_value(row.doctype, row.name, 'weight', parseFloat(weight_per_member))
        );
    });
    
    Promise.all(promises).then(() => {
        frm.refresh_field('panel_members');
        validate_weights(frm);
        update_weight_indicator(frm);
        frappe.show_alert(__('✅ تم توزيع الأوزان تلقائياً'), 2);
    });
}

// 7. إضافة أسئلة نموذجية سريعة
function add_sample_questions(frm) {
    const members = frm.doc.panel_members || [];
    if (members.length === 0) {
        frappe.msgprint(__('⚠️ أضف عضواً في اللجنة أولاً'));
        return;
    }
    
    // البحث عن أول عضو بدون أسئلة
    let target_member = null;
    for (let member of members) {
        const member_doc = frappe.model.get_doc(member.doctype, member.name);
        if (!member_doc.interview_questions || member_doc.interview_questions.length === 0) {
            target_member = member;
            break;
        }
    }
    
    if (!target_member) {
        frappe.msgprint(__('ℹ️ جميع الأعضاء لديهم أسئلة بالفعل'));
        return;
    }
    
    const member_doc = frappe.model.get_doc(target_member.doctype, target_member.name);
    const type = target_member.interviewer_type || 'فني';
    
    // تحديد الأسئلة حسب النوع
    let questions = [];
    if (type === 'HR') {
        questions = [
            {question: "مهارات التواصل", max_score: 25},
            {question: "الانضباط والالتزام", max_score: 25},
            {question: "العمل ضمن الفريق", max_score: 25},
            {question: "الثقافة التنظيمية", max_score: 25}
        ];
    } else if (type === 'إداري') {
        questions = [
            {question: "القيادة واتخاذ القرار", max_score: 30},
            {question: "التخطيط والتنظيم", max_score: 30},
            {question: "إدارة الموارد", max_score: 40}
        ];
    } else { // فني
        questions = [
            {question: "المهارات التقنية الأساسية", max_score: 30},
            {question: "الخبرة العملية", max_score: 40},
            {question: "حل المشكلات", max_score: 30}
        ];
    }
    
    // إضافة الأسئلة
    questions.forEach(q => {
        frappe.model.add_child(
            target_member.doctype, 
            'interview_questions', 
            target_member.name,
            {
                question: q.question,
                max_score: q.max_score,
                given_score: 0
            }
        );
    });
    
    frm.refresh_field('panel_members');
    frappe.show_alert(__('✅ تمت إضافة {0} أسئلة نموذجية', [questions.length]), 2);
}

frappe.ui.form.on('Employee Asset', {
    // Trigger when employee field changes
    employee: function(frm) {
        if (!frm.doc.employee) {
            frappe.msgprint(__("Please select an employee first"));
            return;
        }

        // Clear existing rows
        frm.clear_table('assets');  // Replace 'assets' with your actual child table fieldname

        // Show loading
        frappe.show_alert({
            message: __('Fetching assets for {0}...', [frm.doc.employee]),
            indicator: 'orange'
        });

        // Call server-side function
        frappe.call({
            method: 'moi_app.utils.fetch_employee_assets',
            args: {
                employee: frm.doc.employee
            },
            freeze: true,
            freeze_message: __('Loading assets...'),
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    // Populate child table
                    r.message.forEach(function(asset) {
                        let row = frm.add_child('assets');  // Replace 'assets' with your actual fieldname
                        row.item_name = asset.item_name;
                        row.item_type = asset.item_type;
                        row.quantity = asset.total_quantity;
                        row.item = asset.item_code;  // If you have an item field
                        // Add any other fields you need
                    });

                    // Refresh form to show new rows
                    frm.refresh_field('assets');

                    frappe.show_alert({
                        message: __('✅ Added {0} asset types', [r.message.length]),
                        indicator: 'green'
                    });
                } else {
                    frappe.show_alert({
                        message: __('⚠️ No assets found for this employee'),
                        indicator: 'orange'
                    });
                }
            },
            error: function() {
                frappe.msgprint(__('Failed to fetch assets. Please try again.'));
            }
        });
    }
});

