function duplicate_record(frm) {
    // Create a new document with copied values
    frappe.model.with_doc(frm.doc.doctype, frm.doc.name, function() {
        var new_doc = frappe.model.copy_doc(frm.doc, true);

        // Optional: Clear fields you don't want to copy
          new_doc.visit_type = '';
          new_doc.entry_time = '';
          new_doc.exit_time = '';
          new_doc.visitcardno = '';
          new_doc.visit_reason = '';
          new_doc.notes = '';

        // Open the new document
        frappe.set_route('Form', new_doc.doctype, new_doc.name);
    });
}

