frappe.ui.form.on('Member Evaluation', {
    score(frm, cdt, cdn) {
        let eval_row = locals[cdt][cdn];

        // الوصول إلى صف عضو اللجنة الأب
        let member_row = frappe.get_doc(
            eval_row.parenttype,
            eval_row.parent
        );

        let total_score = 0;
        let total_max = 0;

        member_row.evaluations.forEach(e => {
            total_score += e.score || 0;
            total_max += e.max_score || 0;
        });

        if (total_max > 0) {
            member_row.member_score =
                (total_score / total_max) * member_row.weight;
        } else {
            member_row.member_score = 0;
        }

        frm.refresh_field('committee_members');
    }
});

