frappe.ui.form.on('Member Evaluation', {
    score: calculate_scores,
    committee_member: calculate_scores
});

function calculate_scores(frm) {
    if (!frm.doc.member_evaluations || !frm.doc.interview_round) return;

    let member_totals = {};
    let member_weights = {};

    // جلب الأوزان من Interview Round
    (frm.doc.interview_round_committee || []).forEach(m => {
        member_weights[m.member] = m.weight || 0;
    });

    // جمع العلامات لكل عضو
    (frm.doc.member_evaluations || []).forEach(row => {
        if (!row.committee_member || !row.score) return;

        member_totals[row.committee_member] =
            (member_totals[row.committee_member] || 0) + row.score;
    });

    let final_score = 0;

    Object.keys(member_totals).forEach(member => {
        let weight = member_weights[member] || 0;
        final_score += member_totals[member] * (weight / 100);
    });

    frm.set_value('final_score', final_score);
}

frappe.ui.form.on('Interview', {
    interview_round: function(frm) {
        console.log('Interview Round changed:', frm.doc.interview_round);

        if (!frm.doc.interview_round) return;

        frm.clear_table('committee_members');

        frappe.call({
            method: 'frappe.client.get',
            args: {
                doctype: 'Interview Round',
                name: frm.doc.interview_round
            },
            callback: function(r) {
                console.log('Interview Round data:', r.message);

                if (!r.message) {
                    frappe.msgprint('لم يتم جلب Interview Round');
                    return;
                }

                if (!r.message.committee_members) {
                    frappe.msgprint('لا يوجد Committee Members في Interview Round');
                    return;
                }

                r.message.committee_members.forEach(m => {
                    let row = frm.add_child('committee_members');
                    row.member = m.member;
                    row.member_type = m.member_type;
                    row.weight = m.weight;
                });

                frm.refresh_field('committee_members');
            }
        });
    }
});

