frappe.ui.form.on('Interview', {
    interview_round: function(frm) {
        if (!frm.doc.interview_round) return;

        // تفريغ الجداول
        frm.clear_table('committee_members');
        frm.clear_table('member_evaluations');

        // جلب Interview Round
        frappe.call({
            method: 'frappe.client.get',
            args: {
                doctype: 'Interview Round',
                name: frm.doc.interview_round
            },
            callback: function(r) {
                if (!r.message || !r.message.committee_members) return;

                // لكل عضو لجنة
                r.message.committee_members.forEach(m => {

                    // 1️⃣ نسخ العضو إلى Interview
                    let cm = frm.add_child('committee_members');
                    cm.member = m.member;
                    cm.member_type = m.member_type;
                    cm.weight = m.weight;

                    // 2️⃣ جلب الأسئلة حسب نوع العضو
                    frappe.call({
                        method: 'frappe.client.get_list',
                        args: {
                            doctype: 'Question Panel',
                            filters: {
                                member_type: m.member_type
                            },
                            fields: ['name']
                        },
                        callback: function(q) {
                            if (!q.message) return;

                            // 3️⃣ إنشاء Member Evaluation لكل سؤال
                            q.message.forEach(question => {
                                let me = frm.add_child('member_evaluations');
                                me.committee_member = m.member;
                                me.member_type = m.member_type;
                                me.question = question.name;
                            });

                            frm.refresh_field('member_evaluations');
                        }
                    });
                });

                frm.refresh_field('committee_members');
            }
        });
    }
});
